    fn fail(&mut self, error: LexError) -> LexError {
        self.state = State::Done;
        self.pos = self.src.len();
        error
    }

    /// A closing delimiter at `end` must be followed by a blank or the end of the line.
    fn require_separator_after(&mut self, end: usize) -> Result<(), LexError> {
        match self.bytes().get(end + 1) {
            Some(&byte) if !is_blank(byte) => Err(self.fail(LexError::ExpectedSeparator { pos: end + 1 })),
            _ => Ok(()),
        }
    }

    fn next_field(&mut self) -> Option<Result<Token<'a>, LexError>> {
        let b = self.bytes();
        let start = self.pos + b[self.pos..].iter().take_while(|&&c| is_blank(c)).count();
        let Some(&first) = b.get(start) else {
            self.pos = start;
            return None;
        };
        let token = match first {
            b'[' => self.timestamp(start),
            b'"' => Err(self.fail(LexError::UnexpectedQuote { pos: start })),
            b'=' => Err(self.fail(LexError::EmptyKey { pos: start })),
            _ => self.key_or_word(start),
        };
        Some(token)
    }

    /// `start` is at the `[`.
    fn timestamp(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let b = self.bytes();
        let text_start = start + 1;
        let mut i = text_start;
        loop {
            match b.get(i) {
                None => return Err(self.fail(LexError::UnterminatedTimestamp { pos: start })),
                Some(b']') => break,
                Some(b'[') => return Err(self.fail(LexError::NestedBracket { pos: i })),
                Some(_) => i += 1,
            }
        }
        self.require_separator_after(i)?;
        self.pos = i + 1;
        Ok(Token::Timestamp(&self.src[text_start..i]))
    }

    fn key_or_word(&mut self, start: usize) -> Result<Token<'a>, LexError> {
        let b = self.bytes();
        let mut i = start;
        while i < b.len() && !is_blank(b[i]) && b[i] != b'=' {
            if b[i] == b'"' {
                return Err(self.fail(LexError::UnexpectedQuote { pos: i }));
            }
            i += 1;
        }
        let text = &self.src[start..i];
        if b.get(i) == Some(&b'=') {
            self.state = State::Value;
            self.pos = i + 1;
            Ok(Token::Key(text))
        } else {
            self.pos = i;
            Ok(Token::Word(text))
        }
    }

    fn next_value(&mut self) -> Token<'a> {
        let b = self.bytes();
        let start = self.pos;
        // Reported from the field state onward, whatever the outcome below.
        let _ = b;
        unreachable!("replaced below {start}")
    }
}
