        match self.src.as_bytes().get(end + 1) {
            Some(&byte) if !is_blank(byte) => Err(self.fail(LexError::ExpectedSeparator { pos: end + 1 })),
            _ => Ok(()),
        }
    }

    fn field(&mut self) -> Option<Result<Token<'a>, LexError>> {
        let b = self.src.as_bytes();
        let mut start = self.pos;
        while start < b.len() && is_blank(b[start]) {
            start += 1;
        }
        let Some(&first) = b.get(start) else {
            self.pos = start;
            return None;
        };
        Some(match first {
            b'[' => self.timestamp(start),
            b'"' => Err(self.fail(LexError::UnexpectedQuote { pos: start })),
            b'=' => Err(self.fail(LexError::EmptyKey { pos: start })),
            _ => self.key_or_word(start),
        })
    }

    /// `open` is the offset of the `[`.
    fn timestamp(&mut self, open: usize) -> Result<Token<'a>, LexError> {
        let b = self.src.as_bytes();
        let mut close = open + 1;
        loop {
            match b.get(close) {
                None => return Err(self.fail(LexError::UnterminatedTimestamp { pos: open })),
                Some(b']') => break,
                Some(b'[') => return Err(self.fail(LexError::NestedBracket { pos: close })),
                Some(_) => close += 1,
            }
        }
        self.require_separator_after(close)?;
        self.pos = close + 1;
        Ok(Token::Timestamp(&self.src[open + 1..close]))
    }

